import 'dotenv/config';
import { join, relative, resolve, isAbsolute } from 'node:path';
import { fileURLToPath } from 'node:url';

export const projectRoot = fileURLToPath(new URL('../../', import.meta.url));

/** Persistent data lives in DATA_DIR; point it at a volume that survives redeploys. */
export const dataDirectory = resolve(projectRoot, process.env.DATA_DIR || 'server/data');
export const databasePath = resolve(projectRoot, process.env.SQLITE_PATH || join(dataDirectory, 'wise.sqlite'));
export const uploadDirectory = resolve(projectRoot, process.env.UPLOAD_DIR || join(dataDirectory, 'uploads'));

/** True when a path sits inside the deployed code directory, which most hosts replace on deploy. */
export function insideProject(path) {
  const offset = relative(projectRoot, path);
  return !offset.startsWith('..') && !isAbsolute(offset);
}
